// get_available_slots — Validate Format
// Expected body: { business_id, service, preferred_date, preferred_time }
// business_id is this business's public slug (supabase/migrations/0002_multi_business.sql).
// Format-only checks here; preferred_date/time are re-checked against this
// business's own timezone once it's resolved (see "Resolve Date").
const body = $input.first().json.body || {};

const businessId = String(body.business_id ?? '').trim();
const service = String(body.service ?? body.service_name ?? '').trim();
const preferredDate = String(body.preferred_date ?? '').trim();
const preferredTime = String(body.preferred_time ?? '').trim();

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

const errors = [];
if (!businessId) errors.push('business_id is required');
if (!service) errors.push('service is required');

if (!preferredDate) {
  errors.push('preferred_date is required (YYYY-MM-DD)');
} else if (!DATE_RE.test(preferredDate)) {
  errors.push('preferred_date must be formatted YYYY-MM-DD');
}

if (preferredTime && !TIME_RE.test(preferredTime)) {
  errors.push('preferred_time must be 24-hour HH:MM (or omitted)');
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_id_input: businessId,
    service,
    preferred_date: preferredDate,
    preferred_time: preferredTime || null,
  },
}];

// Normalize Business
// PostgREST returns [] for no match; alwaysOutputData turns that into a
// single item with an empty json object, so presence of `.id` is the
// reliable "did we find a row" test in both shapes.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    business_found: !!row,
    business_id: row ? row.id : null,
    business_name: row ? row.name : null,
    business_timezone: row ? row.timezone : null,
  },
}];

// Normalize Settings
// A missing settings row (business exists but hasn't been configured yet)
// falls back to safe defaults -- no calendar id means the calendar step
// fails honestly downstream instead of guessing one.
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.business_id ? items[0].json : null;

return [{
  json: {
    settings_found: !!row,
    calendar_id: row ? row.calendar_id : null,
    opening_hours: row && row.opening_hours ? row.opening_hours : {},
  },
}];

// get_available_slots — Resolve Date
// Runs after the business (and its timezone) is resolved, so "is this
// date in the past" is evaluated in the business's own timezone rather
// than a hardcoded one.
const input = $('Validate Format').first().json;
const business = $('Normalize Business').first().json;
const tz = business.business_timezone || 'UTC';

const now = DateTime.now().setZone(tz);
const preferred = DateTime.fromISO(input.preferred_date + 'T' + (input.preferred_time || '00:00'), { zone: tz });

const errors = [];
if (!preferred.isValid) {
  errors.push('preferred_date/preferred_time is not a real date and time');
} else if (preferred.startOf('day') < now.startOf('day')) {
  errors.push('preferred_date is in the past');
}

// A time earlier today is a normal thing to say ("this morning") -- roll
// forward to now rather than rejecting the request.
const searchFrom = preferred.isValid && preferred < now ? now : preferred;

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_timezone: tz,
    search_from_iso: searchFrom && searchFrom.isValid ? searchFrom.toISO() : null,
  },
}];

// get_available_slots — Normalize Service
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    service_found: !!row,
    service_id: row ? row.id : null,
    service_name: row ? row.name : $('Validate Format').first().json.service,
    duration_minutes: row ? row.duration_minutes : null,
  },
}];

// get_available_slots — Compute Search Window
const SEARCH_DAYS = 14;
const input = $('Resolve Date').first().json;
const start = DateTime.fromISO(input.search_from_iso, { zone: input.business_timezone });
const end = start.plus({ days: SEARCH_DAYS }).endOf('day');

return [{
  json: {
    search_days: SEARCH_DAYS,
    time_min: start.toUTC().toISO(),
    time_max: end.toUTC().toISO(),
  },
}];

function resolveHours(openingHours, weekdayNum) {
  const DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  const dayName = DAY_NAMES[weekdayNum - 1];
  const schedule = openingHours && Array.isArray(openingHours.schedule) ? openingHours.schedule : null;
  if (!schedule || schedule.length === 0) {
    // Not configured -- fall back rather than guess a business's real hours.
    if (weekdayNum === 7) return { closed: true };
    return { closed: false, open: '09:00', close: '19:00' };
  }
  const row = schedule.find((d) => d && d.day === dayName);
  if (!row) return { closed: true };
  return row.closed ? { closed: true } : { closed: false, open: row.open, close: row.close };
}

// get_available_slots — Compute Available Slots
// Hours come from this business's own business_settings.opening_hours
// (falling back to Mon-Sat 09:00-19:00, closed Sunday, if not configured).
const SLOT_STEP_MINUTES = 15;
const MIN_SLOTS = 2;
const MAX_SLOTS = 3;
const MAX_CANDIDATES = 500;

const dateInput = $('Resolve Date').first().json;
const settings = $('Normalize Settings').first().json;
const service = $('Normalize Service').first().json;
const searchDays = $('Compute Search Window').first().json.search_days;

const tz = dateInput.business_timezone;
const duration = Number(service.duration_minutes);
const searchFrom = DateTime.fromISO(dateInput.search_from_iso, { zone: tz });
const openingHours = settings.opening_hours;

const busy = $input
  .all()
  .map((item) => item.json)
  .filter((e) => e && e.id && e.status !== 'cancelled' && e.transparency !== 'transparent')
  .map((e) => {
    const rawStart = e.start && (e.start.dateTime || e.start.date);
    const rawEnd = e.end && (e.end.dateTime || e.end.date);
    if (!rawStart || !rawEnd) return null;
    return {
      start: DateTime.fromISO(rawStart, { zone: tz }).toMillis(),
      end: DateTime.fromISO(rawEnd, { zone: tz }).toMillis(),
    };
  })
  .filter((b) => b && b.end > b.start);

function overlapsBusy(startMs, endMs) {
  return busy.some((b) => startMs < b.end && endMs > b.start);
}

function ceilToStep(dt) {
  const stepMs = SLOT_STEP_MINUTES * 60 * 1000;
  return DateTime.fromMillis(Math.ceil(dt.toMillis() / stepMs) * stepMs, { zone: tz });
}

const candidates = [];

for (let dayOffset = 0; dayOffset <= searchDays; dayOffset++) {
  const day = searchFrom.plus({ days: dayOffset }).startOf('day');
  const hours = resolveHours(openingHours, day.weekday);
  if (hours.closed) continue;

  const [openH, openM] = hours.open.split(':').map(Number);
  const [closeH, closeM] = hours.close.split(':').map(Number);
  const open = day.set({ hour: openH, minute: openM, second: 0, millisecond: 0 });
  const close = day.set({ hour: closeH, minute: closeM, second: 0, millisecond: 0 });

  let cursor = dayOffset === 0 ? ceilToStep(searchFrom) : open;
  if (cursor < open) cursor = open;

  while (cursor.plus({ minutes: duration }) <= close) {
    const slotEnd = cursor.plus({ minutes: duration });
    if (!overlapsBusy(cursor.toMillis(), slotEnd.toMillis())) {
      candidates.push({ start: cursor, end: slotEnd });
    }
    cursor = cursor.plus({ minutes: SLOT_STEP_MINUTES });
  }

  if (candidates.length >= MAX_CANDIDATES) break;
}

const chosen = [];
for (const candidate of candidates) {
  if (chosen.length === 0) {
    chosen.push(candidate);
  } else {
    const last = chosen[chosen.length - 1];
    if (candidate.start >= last.start.plus({ minutes: duration })) {
      chosen.push(candidate);
    }
  }
  if (chosen.length >= MAX_SLOTS) break;
}

const slots = chosen.map((c) => ({
  start: c.start.toISO(),
  end: c.end.toISO(),
  label: c.start.toFormat("cccc, LLLL d 'at' h:mm a"),
}));

const enough = slots.length >= MIN_SLOTS;
const searchedThrough = searchFrom.plus({ days: searchDays }).endOf('day');
const businessIdInput = $('Validate Format').first().json.business_id_input;

return [{
  json: {
    enough_slots: enough,
    response_ok: {
      business_id: businessIdInput,
      service: service.service_name,
      duration_minutes: duration,
      timezone: tz,
      slot_count: slots.length,
      slots,
    },
    response_error: {
      error: 'no_slots_available',
      message: 'No open ' + service.service_name + ' slots in the next ' + searchDays + ' days. Offer to take a message or transfer to a person.',
      business_id: businessIdInput,
      service: service.service_name,
      duration_minutes: duration,
      timezone: tz,
      searched_from: searchFrom.toISO(),
      searched_through: searchedThrough.toISO(),
      slot_count: 0,
      slots: [],
    },
  },
}];
